    byId('loadContext').onclick=async()=>{try{const result=await post('/v1/context/load'),label=result.scope==='public'?'shared public':'isolated client',sync=result.backend==='adx'?' Synced with '+result.database+' via '+result.routeSource+'.':'';byId('activity').textContent='Indexed '+result.documents+' documents into '+result.chunks+' '+label+' chunks.'+sync;await loadQuick()}catch(error){byId('activity').textContent=error.message}};
