    function fillProfile(){const profile=profiles.find((item)=>item.id===activeProfileId)||profiles[0];if(!profile)return;byId('profileName').value=profile.name;byId('tone').value=profile.tone;byId('voiceStyle').value=profile.voiceStyle;byId('instructions').value=profile.instructions;byId('agentProfile').value=profile.id}function captureProfile(){const profile=profiles.find((item)=>item.id===activeProfileId);if(!profile)return;profile.name=byId('profileName').value||'Unnamed profile';profile.tone=byId('tone').value;profile.voiceStyle=byId('voiceStyle').value;profile.instructions=byId('instructions').value}function fillVoiceProfile(){const voice=voiceProfiles.find((item)=>item.name===activeVoiceName)||voiceProfiles[0];if(!voice)return;activeVoiceName=voice.name;byId('voiceProfile').value=voice.name;byId('voiceInstructions').value=voice.instructions;byId('voiceExaggeration').value=voice.exaggeration;byId('voiceCfgWeight').value=voice.cfgWeight}function captureVoiceProfile(){const voice=voiceProfiles.find((item)=>item.name===activeVoiceName);if(voice){voice.instructions=byId('voiceInstructions').value;voice.exaggeration=Number(byId('voiceExaggeration').value);voice.cfgWeight=Number(byId('voiceCfgWeight').value)}}function refreshProviderFields(){const selected=providerOptions.find((item)=>item.id===byId('provider').value),copilot=selected?.id==='copilot-acp';byId('copilotModel').disabled=!copilot;byId('copilotReasoningEffort').disabled=!copilot;byId('localModel').disabled=copilot}
    function renderKnowledgeProposals(){byId('knowledgeProposals').innerHTML=knowledgeProposalItems.length?knowledgeProposalItems.map((item)=>{const payload=item.payload||{},preview=String(payload.content||('Retire '+payload.sourcePath)).slice(0,500);return '<div class="proposal-item"><div class="proposal-head"><div><span class="proposal-scope">'+esc(item.scope)+'</span><strong>'+esc(payload.title||payload.sourcePath)+'</strong></div><span class="sub">'+esc(item.operation)+'</span></div><p>'+esc(payload.sourcePath)+'\\n'+esc(preview)+'</p><div class="proposal-actions"><button class="small-button primary" data-proposal-action="approve" data-proposal-scope="'+esc(item.scope)+'" data-proposal-id="'+esc(item.id)+'">Approve</button><button class="small-button" data-proposal-action="reject" data-proposal-scope="'+esc(item.scope)+'" data-proposal-id="'+esc(item.id)+'">Reject</button></div></div>'}).join(''):'<div class="empty">No pending proposals.</div>';document.querySelectorAll('[data-proposal-action]').forEach((button)=>button.onclick=async()=>{try{if(button.dataset.proposalAction==='approve'&&!confirm('Publish this proposal to the '+button.dataset.proposalScope+' knowledge database?'))return;await post('/v1/knowledge/'+button.dataset.proposalScope+'/proposals/'+button.dataset.proposalId+'/'+button.dataset.proposalAction);await loadKnowledgeProposals();byId('settingsStatus').textContent=button.dataset.proposalAction==='approve'?'Knowledge proposal published.':'Knowledge proposal rejected.'}catch(error){byId('settingsStatus').textContent=error.message}})}
    async function loadKnowledgeProposals(){const requests=[];if(settings?.activeClientId)requests.push(request('/v1/knowledge/client/proposals').then((data)=>data.proposals).catch(()=>[]));if(settings?.globalKnowledgeEnabled)requests.push(request('/v1/knowledge/public/proposals').then((data)=>data.proposals).catch(()=>[]));knowledgeProposalItems=(await Promise.all(requests)).flat();renderKnowledgeProposals()}
