    byId('saveSettings').onclick=async()=>{try{captureProfile();captureVoiceProfile();settings=await request('/v1/settings',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({modelProvider:byId('provider').value,copilotModel:byId('copilotModel').value,copilotReasoningEffort:byId('copilotReasoningEffort').value,inputModel:byId('localModel').value,ttsEngineUrl:byId('ttsEngineUrl').value,voiceProfile:activeVoiceName,voiceProfiles,clientWorkspace:byId('workspace').value,globalKnowledgePath:byId('globalKnowledgePath').value,globalKnowledgeEnabled:byId('globalKnowledgeEnabled').checked,knowledgeBackend:byId('knowledgeBackend').value,adxClusterUrl:byId('adxClusterUrl').value,adxAuthMode:byId('adxAuthMode').value,adxDefaultDatabase:byId('adxDefaultDatabase').value,adxPublicDatabase:byId('adxPublicDatabase').value,retainSessionLearnings:byId('retainSessionLearnings').checked,activeProfileId,profiles,autonomyDelayMs:Number(byId('autonomyDelay').value),appearanceTheme:byId('appearanceTheme').value,glassTransparency:Number(byId('glassTransparency').value)})});if(settings.clientWorkspace)await request('/v1/client-workspace/knowledge-route',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({database:byId('clientKnowledgeDatabase').value})});applyAppearance(settings.appearanceTheme,settings.glassTransparency);byId('settingsStatus').textContent='Settings saved. Reload context to apply knowledge routing changes.';await loadQuick();await refresh()}catch(error){byId('settingsStatus').textContent=error.message}};
